START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261126080333_AddObserverCheckpoints') THEN
    CREATE TABLE adaptive_checkpoints (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "SessionId" bigint NOT NULL,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "ProcessedThroughUtc" timestamp with time zone,
        "LastBarSeq" integer NOT NULL,
        "Identity" character varying(64) NOT NULL,
        "FormatVersion" integer NOT NULL,
        "PayloadSha256" character varying(64) NOT NULL,
        "Payload" bytea NOT NULL,
        CONSTRAINT "PK_adaptive_checkpoints" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_adaptive_checkpoints_adaptive_sessions_SessionId" FOREIGN KEY ("SessionId") REFERENCES adaptive_sessions ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261126080333_AddObserverCheckpoints') THEN
    CREATE INDEX "IX_adaptive_checkpoints_SessionId_Id" ON adaptive_checkpoints ("SessionId", "Id");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261126080333_AddObserverCheckpoints') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261126080333_AddObserverCheckpoints', '10.0.11');
    END IF;
END $EF$;
COMMIT;

